// TestDecodeClassicSV208LiveFrames freezes exact server frames from captures
// 20260825T195326Z-sv208_classic_boundary_families (events.jsonl SHA-256
// 25aa15fdaeff68a48689bc70e68ddcc519783427a0fd835172c9aaad55246b08)
// and 20260825T195843Z-sv208_tick_news (events.jsonl SHA-256
// 55b765c665166a3c54f791f316211d51ae45fb876e877a028863ca66a5a24dcd).
func TestDecodeClassicSV208LiveFrames(t *testing.T) {
	t.Parallel()

	current := decodeClassicSV208Frame[CurrentTimeMillis](t, classicSV208CurrentTimeMillis)
	if current.TimeMs != "1787687611164" {
		t.Fatalf("CurrentTimeMillis = %+v", current)
	}

	families := decodeClassicSV208Frame[FamilyCodes](t, classicSV208FamilyCodes)
	if len(families.Codes) != 1 || families.Codes[0].AccountID != "*" {
		t.Fatalf("FamilyCodes = %+v", families)
	}

	providers := decodeClassicSV208Frame[NewsProviders](t, classicSV208NewsProviders)
	if len(providers.Providers) != 8 || providers.Providers[0].Code != "BRFG" {
		t.Fatalf("NewsProviders = %+v", providers)
	}

	historical := decodeClassicSV208Frame[HistoricalNewsItem](t, classicSV208HistoricalNews)
	if historical.ReqID != 1 || historical.ProviderCode != "BRFG" || historical.ArticleID != "BRFG$1f064106" || historical.Headline == "" {
		t.Fatalf("HistoricalNewsItem = %+v", historical)
	}
	historicalEnd := decodeClassicSV208Frame[HistoricalNewsEnd](t, classicSV208HistoricalNewsEnd)
	if historicalEnd.ReqID != 1 || !historicalEnd.HasMore {
		t.Fatalf("HistoricalNewsEnd = %+v", historicalEnd)
	}

	article := decodeClassicSV208Frame[NewsArticleResponse](t, classicSV208NewsArticle)
	if article.ReqID != 2 || article.ArticleType != 0 || !strings.Contains(article.ArticleText, "Apple") {
		t.Fatalf("NewsArticleResponse = req=%d type=%d len=%d", article.ReqID, article.ArticleType, len(article.ArticleText))
	}
	displayGroups := decodeClassicSV208Frame[DisplayGroupList](t, classicSV208DisplayGroups)
	if displayGroups.ReqID != 8 || displayGroups.Groups != "1|2|3|4|5|6|7" {
		t.Fatalf("DisplayGroupList = %+v", displayGroups)
	}

	parameters := decodeClassicSV208Frame[ScannerParameters](t, classicSV208ScannerParameters)
	if len(parameters.XML) != 1_801_494 || !strings.HasPrefix(parameters.XML, "<?xml version=") {
		t.Fatalf("ScannerParameters XML length = %d", len(parameters.XML))
	}
	scanner := decodeClassicSV208Frame[ScannerDataResponse](t, classicSV208ScannerData)
	if scanner.ReqID != 3 || len(scanner.Entries) != 10 || scanner.Entries[0].Rank != 0 || scanner.Entries[0].Contract.Symbol != "SWVL" {
		t.Fatalf("ScannerDataResponse = req=%d entries=%+v", scanner.ReqID, scanner.Entries)
	}

	options := decodeClassicSV208Frame[SecDefOptParamsResponse](t, classicSV208SecDefOptParams)
	if options.ReqID != 4 || options.Exchange != "CBOE" || options.UnderlyingConID != 265598 || options.TradingClass != "AAPL" || len(options.Expirations) == 0 || len(options.Strikes) == 0 {
		t.Fatalf("SecDefOptParamsResponse = %+v", options)
	}
	optionsEnd := decodeClassicSV208Frame[SecDefOptParamsEnd](t, classicSV208SecDefOptParamsEnd)
	if optionsEnd.ReqID != 4 {
		t.Fatalf("SecDefOptParamsEnd = %+v", optionsEnd)
	}

	symbols := decodeClassicSV208Frame[MatchingSymbols](t, classicSV208SymbolSamples)
	if symbols.ReqID != 5 || len(symbols.Symbols) != 20 || symbols.Symbols[0].ConID != 265598 || symbols.Symbols[0].Symbol != "AAPL" {
		t.Fatalf("MatchingSymbols = req=%d symbols=%+v", symbols.ReqID, symbols.Symbols)
	}

	depth := decodeClassicSV208Frame[MktDepthExchanges](t, classicSV208MktDepthExchanges)
	if len(depth.Exchanges) != 306 || depth.Exchanges[0].Exchange != "DTB" {
		t.Fatalf("MktDepthExchanges = %+v", depth)
	}

	rule := decodeClassicSV208Frame[MarketRule](t, classicSV208MarketRule)
	if rule.MarketRuleID != 26 || len(rule.Increments) != 1 || rule.Increments[0] != (PriceIncrement{LowEdge: "0", Increment: "0.01"}) {
		t.Fatalf("MarketRule = %+v", rule)
	}

	tiers := decodeClassicSV208Frame[SoftDollarTiersResponse](t, classicSV208SoftDollarTiers)
	if tiers.ReqID != 6 || len(tiers.Tiers) != 0 {
		t.Fatalf("SoftDollarTiersResponse = %+v", tiers)
	}

	components := decodeClassicSV208Frame[SmartComponentsResponse](t, classicSV208SmartComponents)
	if components.ReqID != 12 || len(components.Components) != 0 {
		t.Fatalf("SmartComponentsResponse = %+v", components)
	}

	news := decodeClassicSV208Frame[TickNews](t, classicSV208TickNews)
	if news.ReqID != 1 || news.ProviderCode != "BRFG" || news.Headline == "" {
		t.Fatalf("TickNews = %+v", news)
	}
}

func TestDecodeClassicSV208PnLLiveFrames(t *testing.T) {
	t.Parallel()

	// Capture 20260825T195152Z-sv208_classic_pnl, events.jsonl SHA-256
	// dccee2ab425fca9c707dd682c7d9ffc0dafc1dfd1ce093050e425036a8fcb7d2.
	pnl := decodeClassicSV208Frame[PnLValue](t, classicSV208PnL)
	if pnl.ReqID != 1 || pnl.DailyPnL != "-94.94945599999483" || pnl.RealizedPnL != "0.0" {
		t.Fatalf("PnLValue = %+v", pnl)
	}
	single := decodeClassicSV208Frame[PnLSingleValue](t, classicSV208PnLSingle)
	if single.ReqID != 2 || single.Position != "40" || single.DailyPnL != "95.99609287500061" || single.Value != "59687.998046875" {
		t.Fatalf("PnLSingleValue = %+v", single)
	}
}

func TestDecodeClassicSV208DisplayGroupUpdateLiveFrame(t *testing.T) {
	t.Parallel()

	// Capture 20260825T200425Z-sv208_display_group_updated, events.jsonl SHA-256
	// 8f56c47cc04a67aead4e491d5549d14db323a00fa8e6ad26d0bb1b71e01cd78e.
	update := decodeClassicSV208Frame[DisplayGroupUpdated](t, classicSV208DisplayGroupUpdate)
	if update.ReqID != 1 || update.ContractInfo != "none" {
		t.Fatalf("DisplayGroupUpdated = %+v", update)
	}
}

func decodeClassicSV208Frame[T any](t *testing.T, encoded string) T {
	t.Helper()
	message, err := Decode(208, decodeGzipBase64(t, encoded))
	if err != nil {
		t.Fatal(err)
	}
	value, ok := message.(T)
	if !ok {
		t.Fatalf("Decode() type = %T", message)
	}
	return value
}
